INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-04', '사도행전', '11장 11~20절', '이방인에게 동일한 성령이 임했음을 설명하는 베드로', '사도행전 11장

11   마침 세 사람이 내가 유숙한 집 앞에 서 있으니 가이사랴에서 내게로 보낸 사람이라

12   성령이 내게 명하사 아무 의심 말고 함께 가라 하시매 이 여섯 형제도 나와 함께 가서 그 사람의 집에 들어가니

13   그가 우리에게 말하기를 천사가 내 집에 서서 말하되 네가 사람을 욥바에 보내어 베드로라 하는 시몬을 청하라

14   그가 너와 네 온 집이 구원 받을 말씀을 네게 이르리라 함을 보았다 하거늘

15   내가 말을 시작할 때에 성령이 그들에게 임하시기를 처음 우리에게 하신 것과 같이 하는지라

16   내가 주의 말씀에 요한은 물로 침례를 베풀었으나 너희는 성령으로 침례를 받으리라 하신 것이 생각났노라

17   그런즉 하나님이 우리가 주 예수 그리스도를 믿을 때에 주신 것과 같은 선물을 그들에게도 주셨으니 내가 누구이기에 하나님을 능히 막겠느냐 하더라

18   그들이 이 말을 듣고 잠잠하여 하나님께 영광을 돌려 이르되 그러면 하나님께서 이방인에게도 생명 얻는 회개를 주셨도다 하니라

19   그 때에 스데반의 일로 일어난 환난으로 말미암아 흩어진 자들이 베니게와 구브로와 안디옥까지 이르러 유대인에게만 말씀을 전하는데

20   그 중에 구브로와 구레네 몇 사람이 안디옥에 이르러 헬라인에게도 말하여 주 예수를 전파하니

