4.주제 만들기: 이방인에게 동일한 성령이 임했음을 설명하는 베드로

5.하나님 찾기(관찰)

6.인간 찾기(관찰)

- 할례자들에게 설명하는 베드로

- 베드로의 설명을 듣고 하나님께 영광을 돌리는 할례자들

- 흩어진 자들이 유대인에게만 말씀을 전하다가 몇 사람이 안디옥에 이르러 헬라인에게도 주 예수를 전파함

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 이방인 고넬료를 만났다는 이유로 베드로를 비난하는 할례자들에게 베드로가 상황을 자세히 설명함

- 베드로와 함께 간 여섯 명의 사람들까지 있었기에 그들이 증인이 되었을 것

- 베드로의 설명을 들은 할례자들이 성령 하나님의 역사이심을 인정하고, 비난을 멈춤

- 그리고 하나님께 영광을 돌렸는데 이것은 하나님의 크신 사랑과 은혜를 깨달았기 때문이다.

- 선민사상이 깨지는 것은 어려운 일인데 할례자들이 이렇게 받아들이는 것 또한 하나님의 은혜가 아닐 수 없다.

- 스데반 일로 흩어진 제자들에 의해 복음이 계속 전파된다.

- 복음은 멈추지 않고 전진(확장)한다.

- 그리고 안디옥에 이르러 헬라인에게도 복음이 전파되기 시작한다.

9.적용(나) 

- 복음은 성령을 받은 자를 통해 전파된다. 또한 성령님은 복음 전할 사람을 만나게 하신다.

- 복음은 성장한다. 개인적으로도 자라고, 지역적으로 자란다.

- 복음에는 멈추지 않는 전진성과 생명력이 있다.

- 복음에는 믿는 자들에게 구원을 주시는 하나님의 능력이 있다.

- 이것을 믿는 나도 이 복음을 전해야 한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

