4.주제 만들기: 건강하게 성장하는 교회들

5.하나님 찾기(관찰)

6.인간 찾기(관찰)

- 안디옥 교회 형제들이 서신을 읽고 기뻐하며 받아 들였다.

- 유다와 실라도 형제들에게 권면했고, 얼마 동안 머물다가 돌아갔다.

- 바울과 바나바는 안디옥 교회에 더 머물며 헝제들을 가르쳤다.

- 다른 교회들로 이동하기 전에 마가의 동행 문제로 인해 심하게 다투고 헤어지는 바울과 바나바

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 안디옥 교회 형제들이 교회 지도자들의 결정을 기쁘게 받아들임.

- 예루살렘 교회에서 파송 받은 유다와 실라가 안디옥 교회 형제들에게 말씀으로 권면함.

- 바울과 바나바가 안디옥 교회에 유하며 말씀을 가르치고 전파함.

- 영적 권위가 있는 이들이 안디옥 교회에 와서 말씀을 가르치고 권면하니,

- 안디옥 교회에는 기쁨이 넘쳤을 것이다.

- 권위 있는 자에게 바른 말씀을 듣고 가르침을 받는 것은 얼마나 기쁜 일인가?

- 교회 형제들에게도 말씀을 전한 자들에게도 기쁨이 충만했을 것이다.

- 성령 충만함과 기쁨이 넘치는 가운데, 다른 지역의 교회에도 가서 말씀을 전하고자 하는 바울과 바나바

- 하지만 마가의 동행 문제로 두 사람은 크게 싸우고 헤어지기로 하였다.

- 그러나 두 권위자의 헤어짐은 파국이 아니라, 오히려 복음이 더 넓고 멀리 전파되고 지역 교회들이 단단히 서는데 도움이 되었을 것이다.

- 두 사람이 다툰 것이 좋은 것은 아니지만, 하나님은 모든 것을 합력하여 선을 이루셨다.

  

- 모든 인간은 본성이 있고 삶의 방식이 다르기 때문에 서로 다툴 수 있다.

- 그러나 이것이 악으로 끝나는 것이 아니라 선으로 역전 될 수 있기에 우리는 사람과의 관계를 함부로 생각하거나 판단해서는 안 된다.

9.적용(나) 

- 말씀을 가르치고 배우며 기뻐하는 자가 되고 싶다. 

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-22', '사도행전', '16장 1~10절', '성령의 인도하심에 순종하는 삶', '[행16:1-10]

1 바울이 더베와 루스드라에도 이르매 거기 디모데라 하는 제자가 있으니 그 어머니는 믿는 유대 여자요 아버지는 헬라인이라

2 디모데는 루스드라와 이고니온에 있는 형제들에게 칭찬 받는 자니

3 바울이 그를 데리고 떠나고자 할새 그 지역에 있는 유대인으로 말미암아 그를 데려다가 할례를 행하니 이는 그 사람들이 그의 아버지는 헬라인인 줄 다 앎이러라

4 여러 성으로 다녀 갈 때에 예루살렘에 있는 사도와 장로들이 작정한 규례를 그들에게 주어 지키게 하니

5 이에 여러 교회가 믿음이 더 굳건해지고 수가 날마다 늘어가니라

6 성령이 아시아에서 말씀을 전하지 못하게 하시거늘 그들이 브루기아와 갈라디아 땅으로 다녀가

7 무시아 앞에 이르러 비두니아로 가고자 애쓰되 예수의 영이 허락하지 아니하시는지라

8 무시아를 지나 드로아로 내려갔는데

9 밤에 환상이 바울에게 보이니 마게도냐 사람 하나가 서서 그에게 청하여 이르되 마게도냐로 건너와서 우리를 도우라 하거늘

10 바울이 그 환상을 보았을 때 우리가 곧 마게도냐로 떠나기를 힘쓰니 이는 하나님이 저 사람들에게 복음을 전하라고 우리를 부르신 줄로 인정함이러라

