2025년 10월 26일

사도행전 16장 21절~30절

1.1분기도

2. 본문 성경 읽기(3번)

3. 반복 단어 찾기(형광펜 사용 추천):

옷을 찢어 벗기고 매로 치고/옥에 가두고/차꼬에 든든히 채웠더니: 22절 24절

