18.  바울은 더 여러 날 머물다가 형제들과 작별하고 배 타고 수리아로 떠나갈새 브리스길라와 아굴라도 함께 하더라 바울이 일찍이 서원이 있었으므로 겐그레아에서 머리를 깎았더라

19. 에베소에 와서 그들을 거기 머물게 하고 자기는 회당에 들어가서 유대인들과 변론하니

20. 여러 사람이 더 오래 있기를 청하되 허락하지 아니하고

