4. 주제 만들기:

핍박받는 복음

5. 하나님 찾기 (관찰)

6. 인간 찾기(관찰)

1년 6개월 동안 하나님 말씀을 가르치는 바울.

바울을 대적하는 유대인들.

유대인들로 고소당한 바울에 대하여 회피하는 갈리오 총독.

에베소로 떠나 말씀을 전하며 변론하는 바울. 

 

7. 하나님 찾기(해석)

바울은 1년 6개월 동안 복음을 전했다 그 기간, 1년 6개월은 특별히 하나님의 보호가 있는 시간이었다. 

바울이 그 지역에서 말씀을 가르치기 전에 바울은 조금 위축되어 있었던 것 같다. 

그러한 바울에게 주님은 음성만이 아닌 직접 환상 중에 나타나시어 고린도 지역의 새로운 장소에서 복음을 전할 것을 명령하셨다. 

곧바로 순종한 바울은 고린도의 새로운 지역에서 열심히 복음을 전했다. 일 년 육 개월 동안 순탄하게 그곳에서 말씀을 가르쳤다. 

그 이후에는 과거와 마찬가지로 사탄의 방해가 있었다. 그 지역의 시기 질투하는 유대인들이 일제히 일어나 바울을 새로운 총독 갈리오에게 고소하였다. 

결국 적으로 바울은 그 지역 고린도를 떠나 에베소로 옮겼다. 

이 부분에서 두 가지를 생각했다. 전도는 기회가 있을 때 전파해야 는 것이다. 

주님은 처음부터 1년 6개월이라는 유효기간을 바울에게 알려주지 않으셨다. 마음껏 전파할 수 있는 시간은 하나님만 아신다는 것이다. 

지금 우리 남청연 리더그룹 중심으로 마포대교와 한강대교를 열심히 전도한다. 

늘 전도하는 일상이 아닐 수도 있다. 사탄이 어떠한 공작으로 방해할 수 있다. 선교사를 가장 많이 파송하는 미국조차도 현재 대도시에서 질서유지라는 명분으로 노방전도를 규제하고 있다. 

그러므로 자유롭게 전도를 할 수 있는 것은 노역이 아니고 정해진 시간에 할당된 특권의 시간이다. 

두 번째는 전도의 열매는 하나님 영역이다. 언제 어떻게 열매를 맺을지 아무도 모른다. 

전도자는 그저 전도하는 과정으로만 100% 성공했다 생각된다. 복음을 잘 받는 곳 거부하는 곳, 시간 등이 상황에 따라 예측할 수 없으므로 더욱 그런 것 같다.

8. 인간 찾기(해석)

 9. 적용:

전도의 결과는 하나님 영역임을 깨우친다. 부족한 나를 도구로 사용하시는 하나님의 크신 은혜에 감사하며 복음을 나누는 순간순간을 만족하는 사람이 되어야겠다. 

10. 영적 터치 (단어 또는 구절)

일 년 육 개월을 머물며

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-01-30', '사도행전', '18장 1~10절', '동일한 복음, 다른 선택', '[행18:1-10]

1 그 후에 바울이 아덴을 떠나 고린도에 이르러

2 아굴라라 하는 본도에서 난 유대인 한 사람을 만나니 글라우디오가 모든 유대인을 명하여 로마에서 떠나라 한 고로 그가 그 아내 브리스길라와 함께 이달리야로부터 새로 온지라 바울이 그들에게 가매

3 생업이 같으므로 함께 살며 일을 하니 그 생업은 천막을 만드는 것이더라

4 안식일마다 바울이 회당에서 강론하고 유대인과 헬라인을 권면하니라

5 실라와 디모데가 마게도냐로부터 내려오매 바울이 하나님의 말씀에 붙잡혀 유대인들에게 예수는 그리스도라 밝히 증언하니

6 그들이 대적하여 비방하거늘 바울이 옷을 털면서 이르되 너희 피가 너희 머리로 돌아갈 것이요 나는 깨끗하니라 이 후에는 이방인에게로 가리라 하고

7 거기서 옮겨 하나님을 경외하는 디도 유스도라 하는 사람의 집에 들어가니 그 집은 회당 옆이라

8 또 회당장 그리스보가 온 집안과 더불어 주를 믿으며 수많은 고린도 사람도 듣고 믿어 세례를 받더라

9 밤에 주께서 환상 가운데 바울에게 말씀하시되 두려워하지 말며 침묵하지 말고 말하라

