3.반복단어(같은의미 단어)

4.주제 만들기: 예루살렘을 향하는 바울, 그것을 말리는 형제자매들

5.하나님 찾기(관찰)

- 두로에서 형제들을 통해 예루살렘에 가면 박해가 있을 것을 알려주심

6.인간 찾기(관찰)

- 여러 지방을 거쳐 두로에 도착한 바울 일행

- 형제들이 성령님의 감동을 받고 예루살렘에 들어가지 말라고 말함

- 그들과 여러 날 머물다가 바울 일행이 떠나게 되자, 형제들이 자신의 가족들과 함께 전송하였으며, 바울 일행과 함께 바닷가에 무릎 꿇고 기도함

- 바울 일행이 돌레마이를 거쳐 가이사랴에 이름

- 빌립 집사의 집에 머무름

- 빌립 집사에게는 예언하는 딸 넷이 있었음

- 유대에게 아가보라는 선지자가 내려옴

7.하나님 찾기(해석)

- 하나님께서는 바울이 예루살렘에서 박해 받을 것을 미리 알려주심

- 그곳에서 당할 일을 먼저 알려주심으로 바울의 마음이 더욱 단단하게 준비되도록 도와주신 것으로 생각됨

    

8.인간 찾기(해석)

- 두로에서 제자들을 찾아 그들과 일주일 동안 교제하며 머무름

- 본문에 나오지 않으나 함께 떡을 떼고 필사적으로 기도했을 것임

- 제자들이 기도하던 중 성령님의 감동을 받아, 바울이 예루살렘에서 박해를 받게 될 것을 알고 바울에게 가지 말라고 함

- 여러 날을 더 머물다가 떠날 때, 제자들의 가족들이 함께 전송하고 헤어지기 전에 무릎을 꿇고 기도함

- 이 것을 통해 제자의 가족들이 바울을 얼마나 많이 사랑했는지 엿볼 수 있음.

- 이들은 바울이 예루살렘으로 떠나면 박해를 받을 것이고, 나아가 앞으로 다시는 못 볼 것을 알기에 슬퍼하며, 그러나 성령님의 도우심을 구하며 기도했을 것이다.

- 바울 일행이 빌립 집사의 집에 가서 머물렀다.

- 빌립 집사와 바울이 얼마나 서로를 반겼을지, 그들이 어떤 대화를 나누고 기도를 했을지 그 모습이 참으로 궁금하다.

- 빌립 집사의 딸들은 예언하는 사람들이었다.

- 빌립 집사가 성령을 받고 평소에 가정에서 어떻게 살았고 자녀 교육을 어떻게 했는지 예상할 수 있는 부분이다. 물론 믿음을 자라게 하시는 이는 하나님이시다.

- 유대에서 아가보라 하는 선지자가 내려왔다.

- 아가보라는 선지자를 통해 성경에 나오지는 않지만, 당시에 성령 충만을 받은 믿음의 사람들이 더 많았을 것임을 유추해 볼 수 있다.

9.적용(나) 

- 기도하되 필사적으로 해야 한다.

- 지금 내게는 복음 전파에 간절함이 없다.

- 사도행전 시대에 제자들에게는 복음 전파에 간절함이 있었는데,

- 오늘날 지금 내게는 왜 간절함이 없는가. 나는 왜 정체되어 있는가.

- 마음과 목숨과 뜻과 힘을 다한 사랑과 기도가 있어야 한다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
