- 이 말을 듣고 바리새인과 사두개인이 다툼

- 천부장이 바울이 다칠까 염려하여 부하들에게 바울을 데리고 영내로 들어가라 명함

 

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 바울이 양심을 따라 하나님을 섬겼다고 말하자 대제사장 아나니아가 바울의 입을 치라고 명함

- 예수님을 구주로 믿고 그것을 전하는 바울이 하나님을 바르게 섬겼다고 한 것이 대제사장 입장에서는 바울의 입을 치게 만드는 말이었을까?

- 바울이 아나니아를 말씀을 근거로 비난함.

- 공회 사람들이 아나니아가 대제사장인데 네가 욕하느냐 묻자,

- 바울은 그가 대제사장인줄 몰랐다고 말하며 말씀을 근거로 자신의 실수를 인정함

- 바울이 공회에 모인 사람들이 바리새인과 사두개인이 있다는 것을 알고 죽은 자의 소망 곧 부활 때문에 심문을 받는 중이라고 말함

- 이 말을 들은 바리새인은 부활이 있다고 주장하고 사두개인은 없다고 주장하면서 다툼이 일어남

- 바울을 잡아 죽이려하던 자들이 자신의 신념을 지키고자 서로 다투다가, 바리새인 서기관 중 일부가 바울은 죄가 없다고 공회에서 선언까지 하게 됨

- 부활이라는 절묘한 수를 사용한 바울의 지혜도 놀랍지만,

- 그 부활이 뜻하는 바가 예수님이 바로 구주이며, 하나님이라는 증거인데 그 말의 깊이는 전혀 알지 못하고, 자신의 지식과 신념 때문에 바울을 옹호하는 바리새인들도 놀라울 따름이다.

- 사람들은 자신이 쌓아온 지식과 신념, 세계관을 지키기 위해 싸우는 존재들이다.

- 전도자들은 이것을 기억하고 불신자에게 복음을 전할 때 지혜롭게 행동해야 한다.

- 천부장이 부하들에게 바울을 데리고 영내로 들어가라고 명령함

- 로마 시민인 바울을 보호하기 위함 

9.적용(나) 

- 내가 쌓아온 지식과 신념은 바른 것인가?

- 복음 앞에서 바른 것인가?

- 주께서 내게 주신 믿음은 바른 것이다. 그렇지만 이 믿음 안에서 생겨난 나의 지식과 신념은 모두 바른 것일까?

- 예수님 앞에서, 말씀 앞에서 깊이 생각하고 신중하게 행동해야 한다.

- 잘못을 저지르고도 그것이 잘못인지조차 모르는 때가 많을 것이다.

- 불신자에게 복음을 전할 때에는 항상 말에 조심해야 한다. 그들 중에는 교인에 대한 나쁜 기억이 있을 수 있고, 이런 기억이 없더라도 기독교는 나쁘다는 신념이 있을 수 있다.

