19. 천부장이 그의 손을 잡고 물러가서 조용히 묻되 내게 할 말이 무엇이냐

20. 대답하되 유대인들이 공모하기를 그들이 바울에 대하여 더 자세한 것을 묻기 위함이라 하고 내일 그를 데리고 공회로 내려오기를 당신께 청하자 하였으니

