4.주제 만들기: 로마군의 호위를 받으며 로마로 향하는 바울

5.하나님 찾기(관찰)

6.인간 찾기(관찰)

- 바울의 생질이 천부장에게 유대인들이 바울을 죽이려고 매복한 사실을 알림

- 천부장이 청년에게 이 사실을 알게 된 것을 알리지 말라고 함

- 천부장이 백부장 둘을 불러 무장을 하고 바울을 짐승에 태워 총독에게 갈 것을 명령함    

- 천부장이 총독에게 편지를 써서 보냄

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 바울의 생질이 천부장에게 가서 바울의 위험을 알리고 천부장이 이것을 받아들였는데,

- 만약 바울이 로마 시민이 아니었다면 바로 거절당했을 것임

- 바울의 생질이 매복한 사실을 알게 된 것도 바울이 로마 시민인 것도 모두 하나님의 놀라움 섭리 속에 있음

- 천부장이 정보가 새나가지 않도록 청년에게 이 사실을 함구할 것을 조치하고,

- 즉시 백부장을 불러 병력을 무장하고 바울을 호위할 것을 명령함

- 나아가 바울을 태우고 갈 짐승을 준비하라고 함

- 바울은 로마에 복음을 전하러 가야하는데, 

- 이 사건 없이 스스로 갔다면 자비량이기 때문에 비용도 많이 들고 험한 길을 가야 하기 때문에 체력도 많이 써야 했음.

- 그러나 하나님의 도우심으로 인해 로마 국비로 로마에 복음을 전하는 국비선교사가 되었음.  

- 하나님께서는 바울을 로마에 보내시되, 그냥 보내시지 않고 독수리 날개로 바울을 업어 로마로 이동시키시는 것이다.

- 천부장이 병력 두 개 중대를 보내는 동시에 총독에게 편지를 써서 보냄

- 그의 일처리의 신속함과 치밀함을 알 수 있음

- 그러나 내용을 보면 바울을 심문하기 위해 채찍질하려고 했던 사실을 빼고,

- 자신이 로마 시민인 바울을 구해왔다는 내용만 씀

- 물론 그런 내용까지 구구절절 다 쓸 필요는 없지만, 자신의 잘 한 점만 부각시키는 것은 인간의 본성임

9.적용(나) 

- 지금 고난 중에 있더라도, 

- 사실은 하나님께서 암탉이 알을 품듯이, 

- 독수리 날개를 우리를 업고 날아가듯이,

- 늘 우리를 지키시고 보호하고 계시다는 것을 기억해야 한다.

- 느껴지지 않든, 믿기지 않든, 이것은 사실이다.

- 하나님은 고난과 핍박까지도 합력하여 선을 이루시는 선한 하나님이시다.

- 고난 중일 때 울자, 실컷 울자. 그러나 안아주시는 주님을 바라보자.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-19', '사도행전', '23장 31~35절', '총독 앞에서 복음을 전하게 된 바울', '[행23:31-35]

31 보병이 명을 받은 대로 밤에 바울을 데리고 안디바드리에 이르러

32 이튿날 기병으로 바울을 호송하게 하고 영내로 돌아가니라

33 그들이 가이사랴에 들어가서 편지를 총독에게 드리고 바울을 그 앞에 세우니

34 총독이 읽고 바울더러 어느 영지 사람이냐 물어 길리기아 사람인 줄 알고

35 이르되 너를 고발하는 사람들이 오거든 네 말을 들으리라 하고 헤롯 궁에 그를 지키라 명하니라

