3. 반복단어 찾기(형광펜 추천)

- 바울(31,32,33,34절)

- 총독(33,34절)

4. 주제만들기: 총독 앞에서 복음을 전하게 된 바울

5. 하나님 찾기 (관찰)

- 하나님의 뜻 가운데 바울을 로마로 인도하심

6. 인간 찾기 (관찰)

- 바울을 안디바드리에 데리고 가서 기병이 호송하게 인계하는 보병

- 가이사랴에 들어가 총독 앞에 서는 바울

- 어느 영지 사람이냐 묻고 길리기아 사람인 줄 알자 고발한 사람들 앞에서 이야기를 듣겠다 말하는 총독

7. 하나님 찾기 (해석)

- 하나님께서 이루고자 하시면 고난과 어려운 상황 속에서도 복음은 이어진다.

8. 인간(해석):

- 오늘은 기병을 타고 이동하는 바울의 모습이 떠오른다. 담대한 모습인지, 덤덤한 모습인지, 마지막을 생각하는 모습인지 알 수 없다. 

- 두려운 마음이 들 수도 있었지만 하나님께선 직접 말씀해주셨다. “담대하라”

- 하나님께서 직접 응답하신 이 말이 바울에게 얼마나 큰 위로와 힘이 되었을까? 

- 지금 바울 곁엔 아무도 없다. 그러나 외롭지 않았을 것이다. 

- 우리 안에는 성령님이 내주하신다. 우리가 감당해야 할 소명과 삶과 역할 가운데, 선하고 의로운 일을 하는 과정에서 겪는 외로움, 씁쓸함, 갈등은 성령님을 통해 위로받고 용기를 얻을 수 있다. 이게 맞나라는 생각이 들 때 하나님을 더 붙잡아야겠다. 

- 바울은 가이사랴에 들어가 총독을 대면한다. 그리고 자신은 길리기아 사람이라며 자신의 정체성을 드러냈다. 

- 만약 제자 중 누군가 사울의 사명을 담당했다면 관리자들은 그 사람을 무시했을 것 같다. 

- 그러나 바울처럼, 바리새인 중에 바리새인이며, 학식이 뛰어나고, 정체성이 명확한 사람이기에 그의 말을 한번이라도 들어보려는 마음이 들지 않았을까 생각해본다.

9. 적용(나): 

- 하나님을 더욱 의지하고, 맡겨주신 소명에 감사해야겠다.

10. 영적터치(단어/구절)

너를 고발하는 사람들이 오거든 네 말을 들으리라

11. 믿음과 회개 및 감사기도로 마무리

12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-20', '사도행전', '24장 11~20절', '총독 벨릭스에게 변명하는 바울.', '(사도행전 24장)

11. 당신이 아실 수 있는 바와 같이 내가 예루살렘에 예배하러 올라간 지 열이틀밖에 안 되었고

12. 그들은 내가 성전에서 누구와 변론하는 것이나 회당 또는 시중에서 무리를 소동하게 하는 것을 보지 못하였으니

13. 이제 나를 고발하는 모든 일에 대하여 그들이 능히 당신 앞에 내세울 것이 없나이다

14. 그러나 이것을 당신께 고백하리이다 나는 그들이 이단이라 하는 도를 따라 조상의 하나님을 섬기고 율법과 선지자들의 글에 기록된 것을 다 믿으며

15. 그들이 기다리는 바 하나님께 향한 소망을 나도 가졌으니 곧 의인과 악인의 부활이 있으리라 함이니이다

16. 이것으로 말미암아 나도 하나님과 사람에 대하여 항상 양심에 거리낌이 없기를 힘쓰나이다

17. 여러 해 만에 내가 내 민족을 구제할 것과 제물을 가지고 와서

18. 드리는 중에 내가 결례를 행하였고 모임도 없고 소동도 없이 성전에 있는 것을 그들이 보았나이다 그러나 아시아로부터 온 어떤 유대인들이 있었으니

19. 그들이 만일 나를 반대할 사건이 있으면 마땅히 당신 앞에 와서 고발하였을 것이요

20. 그렇지 않으면 이 사람들이 내가 공회 앞에 섰을 때에 무슨 옳지 않은 것을 보았는가 말하라 하소서

