2025년 11월 23일

사도행전 24장 11절~20절

1.1분기도

2. 본문 성경 읽기(3번)

3. 반복 단어 찾기(형광펜 사용 추천):

보지 못하였으니/ 보았는가: 12절 20절

고발: 13절 19절

성전: 12절 18절

하나님: 14절 15절 16절 

바울: 12절 13절 14절 16절 17절 18절 19절 20절

총독 벨릭스: 11절 14절  

4. 주제 만들기:

총독 벨릭스에게 변명하는 바울.

5. 하나님 찾기 (관찰)

모든 민족의 조상 되신 하나님.

6. 인간 찾기(관찰)

총독에게 자신의 상황을 사실 그대로 말하는 바울.

양심대로 바르게 살아가는 바울.

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

바울은 담대하면서도 의연하게 총독 벨릭스 에게 자신의 상황을 사실적 기반에 두고 말했다. 

그는 예루살렘에 온 지 12일밖에 되지 않았다고 했다. 그만큼 짧은 시간 동안 소동을 부릴 수 없었음을 말한 것이다. 

또 하나는 자신을 박해하는 종교 지도자들이 믿는 하나님에 대하여 자신도 유대의 전통적 신앙이 있다고 했다. 

다만 예수그리스도를 통한 더욱 구체적인 하나님이 원하시는 율법을 가르치고자 한 것이다. 

마지막으로 결정적인 것은 바울은 하나님과 사람에 대하여 항상 "양심"에 거리낌이 없기를 힘썼다고 고백했다. 

바울은 단지 위기를 모면하기 위했다면 그의 좋은 출신과 배경을 내세웠을 것이다. 

하지만 바울은 오직 자신을 이끄신 주님 사랑의 고백 즉" 양심"의 소리를 따라 순종함이 나타난다. 

이것이 바울을 더욱 담대하게 만들어준 것 같다. 

신앙인이라면 누구나 마음에서 보내는 올바른 신호인 양심의 소리를 잘 들어야겠다.

 9. 적용(구체적으로)

양심을 통하여 인도하시는 성령 하나님의 음성을 듣기 위하여 더욱 힘써야겠다.

10. 영적 터치 (단어 또는 구절)

16절: 하나님과 사람에 대하여 항상 양심에 거리낌이 없기를 힘쓰나이다

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-21', '사도행전', '24장 1~10절', '고발당한 바울', '(사도행전 24장)

1. 닷새 후에 대제사장 아나니아가 어떤 장로들과 한 변호사 더둘로와 함께 내려와서 총독 앞에서 바울을 고발하니라

2. 바울을 부르매 더둘로가 고발하여 이르되

3. 벨릭스 각하여 우리가 당신을 힘입어 태평을 누리고 또 이 민족이 당신의 선견으로 말미암아 여러 가지로 개선된 것을 우리가 어느 모양으로나 어느 곳에서나 크게 감사하나이다

4. 당신을 더 괴롭게 아니하려 하여 우리가 대강 여짜옵나니 관용하여 들으시기를 원하나이다

5. 우리가 보니 이 사람은 전염병 같은 자라 천하에 흩어진 유대인을 다 소요하게 하는 자요 나사렛 이단의 우두머리라

6. 그가 또 성전을 더럽게 하려 하므로 우리가 잡았사오니 (6하반-8상반 없음)

8. 당신이 친히 그를 심문하시면 우리가 고발하는 이 모든 일을 아실 수 있나이다 하니

9. 유대인들도 이에 참가하여 이 말이 옳다 주장하니라

10. 총독이 바울에게 머리로 표시하여 말하라 하니 그가 대답하되 당신이 여러 해 전부터 이 민족의 재판장 된 것을 내가 알고 내 사건에 대하여 기꺼이 변명하나이다

3331 생명의 큐티

3:하나님, 인간, 나

3:관찰, 해석, 적용

3:반복 단어 찾기, 질문하기, 대상이 되어봄(본문)

1:감동하는 단어나 구절 찾기(영적 터치)

2025년 11월 22일

사도행전 24장 1절~10절

1.1분기도

2. 본문 성경 읽기(3번)

3. 반복 단어 찾기(형광펜 사용 추천):

고발: 1절 2절 8절

전염병/소요/이단의 우두머리: 5절

바울: 1절 2절 4절 5절 6절 8절 10절

총독 벨릭스: 3절 8절 10절 

4. 주제 만들기:

고발당한 바울

5. 하나님 찾기 (관찰)

6. 인간 찾기(관찰)

바울을 로마 총독 벨릭스에게 고발한 대제사장과 장로들.

고발자들이 바울에게 심한 모욕적인 말을 함. 

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

바울은 엘리트 출신이다. 그러한 바울을 향하여 유대인의 종교적 기득권층이라 할 수 있는 대제사장과 장로들 그리고 일반 유대인까지 합세하여 바울을 인신공격하였다. 

바울에게 ''이단'' 또는 ''전염병 같은 자'' 그리고 ''성전을 더럽게'' 등의 용어를 사용하며 그에게 큰 수치감을 주었다. 

이때 바울은 요동치지 않고 차분하게 대응했다. 그리고 로마 총독 벨릭스에게 ''이 민족의 재판장 된 것을'' 표현하며 변명하기 시작했다. 

바울이 이러한 억울하고 모멸감 느낄 수 있는 환경에서도 차분할 수 있는 것은 주님께서 바로 얼마 전에 나타나셔서 ''담대하라'' 말씀하신 부분이 클 것이다. 

그리고 주님은 바울이 로마까지 갈 것을 미리 알려주셨다. 그러므로 바울은 현재 서 있는 가이사랴 지역에 오래 있지 않을 것을 알았을 것이다. 

그가 담대한 또 다른 이유는 참 재판장은 총독 벨릭스가 아니라 우주 만물과 인간을 지으시고 살리시기도 하시고 죽이시기도 하시는 전능하신 하나님이심을 믿었기 때문이다. 

이러한 깨우침을 마음에 간직한다면 주님을 믿는 누구든지 어떠한 고난의 환경에서도 평정심을 유지할 것이라 믿어진다.

 9. 적용(구체적으로)

참 심판자가 되신 주님을 더욱 의지하는 삶을 살아내야겠다.

10. 영적 터치 (단어 또는 구절)

10절: 재판장

11. 믿음과 회개 및 감사기도로 마무리', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-02-22', '사도행전', '25장 1~10절', '바울이 가이사에게 상소하다', '사도행전 25장

1   베스도가 부임한 지 삼 일 후에 가이사랴에서 예루살렘으로 올라가니

2   대제사장들과 유대인 중 높은 사람들이 바울을 고소할새

3   베스도의 호의로 바울을 예루살렘으로 옮기기를 청하니 이는 길에 매복하였다가 그를 죽이고자 함이더라

4   베스도가 대답하여 바울이 가이사랴에 구류된 것과 자기도 멀지 않아 떠나갈 것을 말하고

5   또 이르되 너희 중 유력한 자들은 나와 함께 내려가서 그 사람에게 만일 옳지 아니한 일이 있거든 고발하라 하니라

6   베스도가 그들 가운데서 팔 일 혹은 십 일을 지낸 후 가이사랴로 내려가서 이튿날 재판 자리에 앉고 바울을 데려오라 명하니

7   그가 나오매 예루살렘에서 내려온 유대인들이 둘러서서 여러 가지 중대한 사건으로 고발하되 능히 증거를 대지 못한지라

8   바울이 변명하여 이르되 유대인의 율법이나 성전이나 가이사에게나 내가 도무지 죄를 범하지 아니하였노라 하니

9   베스도가 유대인의 마음을 얻고자 하여 바울더러 묻되 네가 예루살렘에 올라가서 이 사건에 대하여 내 앞에서 심문을 받으려느냐

10   바울이 이르되 내가 가이사의 재판 자리 앞에 섰으니 마땅히 거기서 심문을 받을 것이라 당신도 잘 아시는 바와 같이 내가 유대인들에게 불의를 행한 일이 없나이다

