- 바울을 돌보아주는 벨릭스

- 바울을 불러 복음을 듣는 벨릭스

- 심판을 듣고 두려워 하는 벨릭스

- 바울에게 돈을 받을 수 있을까하는 마음에 바울을 자주 부르는 벨릭스

- 유대인의 마음을 얻기 위해 바울을 구류하는 벨릭스

7. 하나님 찾기 (해석) 

8. 인간(해석):

- 담대했던 바울은 복음을 소리쳤다. 예수님의 죽음과 부활, 복음의 핵심 내용을 선포하였다. 

- 외로운 상황에서 오히려 담대했던 바울의 모습을 상상해보니 뭉클하다. 

- 나도 이런 상황에서 복음을 전할 수 있는 용기가 있어야겠다.

- 벨릭스는 바울을 따로 불러 복음을 들었다. 그러나 복음을 받아들이지 않았다.

- 오히려 바울을 부르며 바울에게 돈을 받을 수 있을까 생각했다.

- 복음을 받아들이는건 하나님의 은혜 없인 불가능한 일이다. 

- 복음을 들었음에도 회피했던 벨릭스가 불쌍하다.

- 그리고 복음을 제대로 알지 못했던 내게 찾아오신 하나님께 감사드린다.

