4.주제 만들기: 유라굴로 광풍을 만나다

5.하나님 찾기(관찰)

6.인간 찾기(관찰)

- 백부장이 바울의 말보다 선장과 선주의 말을 더 믿고 항해하기로 결정함

- 남풍이 순하게 불자 항해를 시작했으나 곧 유라굴로라는 광풍을 만남

- 폭풍이 심하여 거룻배(작은 배)를 선체에 올리고 줄로 묶어 놓음

- 닻을 내렸으나 바람에 끌려 감

- 폭풍을 이겨내기 위해 애쓰다가 이튿날 사공들이 짐을 바다에 버림

- 셋째 날에는 사공들이 배의 기구도 버림

- 여러 날 동안 해도 별도 보이지 않는 폭풍 속에 있었으므로 살 수 있다는 생각마저 사라졌다.

7.하나님 찾기(해석)

8.인간 찾기(해석)

- 백부장은 항해 전문가인 선장과 선주의 말을 바울의 말보다 신뢰함

- 바울은 이 전에 경험한 선교 여행을 통해 금식 기간이 끝난 시기부터는 항해하기 힘든 날씨가 온다는 것을 알고 있었을 것이다.

- 마침 남풍이 순하게 불었고 항해를 출발했으나 곧 유라굴로(북동풍)라는 폭풍이 왔다. 

- 이 폭풍이 얼마나 셌는지 광풍이라 표현했으며, 

- 거룻배를 선체에 올리고 줄로 묶었고, 닻을 내렸으나 배가 바람에 끌려갔다.

- 사공들이 짐을 버릴 정도로 사력을 다해 싸웠으나 폭풍 위에서 배와 생명이 위태로워, 배의 기구를 버릴 정도로 큰 폭풍이었다.

- 영화를 보면 배가 크게 흔들리고 물이 배 위로 들이쳐 사람들이 휩쓸려 가지 않기 위해 사력을 다하는 장면을 볼 때가 있는데, 그것과 비슷한 모습이었을 것이다.

- 이 폭풍이 여러 날 지속되어 해와 달도 보지 못했고 며칠 동안 밥도 못 먹어 굶주렸을 것이다.

- 이들에게 드는 생각이라곤 ‘버틸 수가 없다.’ ‘곧 죽을 수 밖에 없다.’ 이런 것들일 것이다.

9.적용(나) 

- 백부장은 합리적인 판단을 했으나, 큰 위험을 당하게 되었다.

- 일을 그르친 정도가 아니라, 생명의 위협을 당하게 된 것이다.

- 사람의 합리적인 판단이 사람을 죽게 만들 수도 있다.

- 바울은 복음을 전하러 가는 길에서 큰 위험을 만났다.

- 로마로 가라는 주님의 명령을 받았고, 주님의 도움을 받으며 여기까지 왔는데, 

- 만난 것은 광풍이다.

- 주님의 꿈을 이루는 통로로 사용되는 것이 보통 어려운 일이 아니라는 것을 알 수 있다. 

- 모든 것을 합력하여 선을 이루시는 하나님을 바라며 견딜 뿐이다.

10.영적 터치(단어/구절)

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2025-03-03', '사도행전', '27장 21~30절', '광풍으로 두려워하는 사람들을 안심시키는 바울.', '(사도행전 27장)

21. 여러 사람이 오래 먹지 못하였으매 바울이 가운데 서서 말하되 여러분이여 내 말을 듣고 그레데에서 떠나지 아니하여 이 타격과 손상을 면하였더라면 좋을 뻔하였느니라

22. 내가 너희를 권하노니 이제는 안심하라 너희 중 아무도 생명에는 아무런 손상이 없겠고 오직 배뿐이리라

23. 내가 속한 바 곧 내가 섬기는 하나님의 사자가 어젯밤에 내 곁에 서서 말하되

24. 바울아 두려워하지 말라 네가 가이사 앞에 서야 하겠고 또 하나님께서 너와 함께 항해하는 자를 다 네게 주셨다 하였으니

25. 그러므로 여러분이여 안심하라 나는 내게 말씀하신 그대로 되리라고 하나님을 믿노라

26. 그런즉 우리가 반드시 한 섬에 걸리리라 하더라

27. 열나흘째 되는 날 밤에 우리가 아드리아 바다에서 이리저리 쫓겨가다가 자정쯤 되어 사공들이 어느 육지에 가까워지는 줄을 짐작하고

28. 물을 재어 보니 스무 길이 되고 조금 가다가 다시 재니 열다섯 길이라

29. 암초에 걸릴까 하여 고물로 닻 넷을 내리고 날이 새기를 고대하니라

30. 사공들이 도망하고자 하여 이물에서 닻을 내리는 체하고 거룻배를 바다에 내려놓거늘

