4. 주제 만들기:

광풍으로 두려워하는 사람들을 안심시키는 바울.

5. 하나님 찾기 (관찰)

천사를 보내어 바울을 안심시키시는 하나님

6. 인간 찾기(관찰)

광풍으로 두려움에 떨고 있는 배에 탑승한 사람들을 안심시키는 바울.

7. 하나님 찾기(해석)

하나님은 장차 일어날 광풍을 말씀하시고 안전하게 로마로 항해할 것을 바울에게 미리 알려주심으로 바울을 안심시키셨다. 

8. 인간 찾기(해석)

같은 배를 탔는데 두려움과 안정된 마음이 공존한다. 

바울은 바다의 풍랑이 일어나기  하루 전에 하나님의 사자가 나타나 바울에게 안전하게 로마까지 갈 것을 미리 알려주었다. 

그럴 뿐만 아니라 21절에 보면 바울은 인솔자 백부장에게 왜 자기 말을 듣지 않고 출항했는지 말할 것 보면 천사를 만난 하루보다 이전에 일어날 위기를 이미 알고 있었음을 가늠할 수 있다. 

이것을 보면 바울은 늘 주님과  동행하는 사람인 것을 알 수있다.

이러한 모습이 개인적으로 너무 부럽다. 어떠한 어려움의 환경에서도 좌고우면하지 않는 태도이다. 

그러므로 일상 생활가운데 성령 하나님과 교제하는 것이 얼마나 중요한지 알 수 있다. 

바울은 떨고 있는 배에 함께 있는 많은 사람에게 안심과 위로를 주었다. 

마찬가지로 우리 남청연(남북 청년연합 선교회)도 혹시 광풍처럼 어려움이나 위기가 오더라도 하나님이 함께하신다면 안전한 영적 항해가 될 것을 믿는다.

9. 적용(구체적으로)

오늘은 한강대교로 전도를 간다. 날씨가 비록 상당히 추울 것으로 예상되지만 준비된 영혼을 향하여 주님과 함께 뜨거운 복음을 전해야 하겠다. 

10. 영적 터치 (단어 또는 구절)

24절: 바울아 두려워하지 말라

