6. 인간 찾기(관찰)

복음을 들은 적이 없다고 말하는 유대인들.

가택연금 가운데 복음을 가르치는 바울.

7. 하나님 찾기(해석)

8. 인간 찾기(해석)

바울은 드디어 최종 목적지인 로마로 들어갔다. 

그곳에서도 담대하며 거침없이 복음을 전파하였다. 

그는 이사야 선지자 말을 인용하기도 하였다. 내용을 보면 "백성들의 마음이 우둔하여져서 그 귀로는 둔하게 듣고 그 눈은 감았으니" 기록된 것을 알 수 있다. 

선지자 이사야가 활동했던 BC 700년 전에도 하나님 나라 말씀은 전파되었고 그 말씀을 듣고 받는 자와 거부하는 자가 있었다. 

사도바울이 활동했던 약 2000년 전에도 마찬가지였고 현재 2025년도에도 일어나는 현상은 비슷하다. 

그러면 시대적으로 누군가가 자신의 삶을 헌신하면서까지 복음을 전파하는 것은 무모한 일인 것일까?

결코 아니다. 시대별로 사탄의 역사로 사람들의 마음이 우둔하여져서 복음을 받아들이지 않는 경우가 있더라도 분명 나아지고 있음을 현실적 사실적 데이터로 입증되고 있다. 

과거에서 출발하여 현재로 올수록 기독교를 믿는 비율이 세계적으로 올라가고 있음을 알 수 있다. 

이 모든 것은 하나님의 전적인 영혼을 사랑하시는 열정이고 그에 순종하고 일하는 일꾼들의 거침없는 복음 전파의 산물이다. 

나도 그러한 하나님의 비전에 끊임없이 참여 받는 복을 누리고 싶다. 

이 영적인 복을 사랑하는 우리 남청연(남북 청년 연합선교회)과 함께 하기를 바란다.

