4.주제 만들기: 믿는 자에게 주시는 은혜의 약속 

5.하나님 찾기(관찰)

- 모든 믿는 자를 세상의 상속자가 되게 하심 

- 죽은 자를 살리시며 없는 것을 있는 것으로 부르신다.

6.인간 찾기(관찰)

- 아브라함은 할례를 받기 전에 이미 믿음으로 의로움을 얻었고, 할례를 받음으로 믿음으로 의로움을 얻은 것을 확인받았다.

- 아브라함으로 인해 앞으로 하나님을 믿게 될 할례 받지 않은 모든 사람 또한 의로움을 인정받게 하시는 것이다.

- 아브라함은 바랄 수 없는 중에 바라고 믿었다.

7.하나님 찾기(해석)

- 하나님은 믿음으로 우리를 의롭다 하시고 동시에 세상의 상속자가 되게 하신다.

- 하나님은 부활과 창조의 하나님이시다.

8.인간 찾기(해석)

- 율법은 죄를 깨닫게 하는 역할을 할 뿐 사람이 율법을 지키는 행위로써는 의에 이를 수 없다. 오직 믿음으로만 은혜로 의에 이를 수 있다.

- 하나님의 상속자가 되는 약속 또한 율법이 아니라 믿음으로 되는 것이다

- 이 약속은 모세를 통해 율법이 선포되기 전에 이미 아브라함에게 주신 약속임을 바울은 선포한다

- 바울은 이것을 통해 율법보다 믿음이 먼저라는 것을 강조하는 것이다.

- 이 말은 유대인과 이방인 모두에게 큰 깨달음과 확신을 준다.

- 아브라함은 언약대로 모든 민족의 조상이 되고 믿음으로 구원받는 모든 사람의 조상이 된다.

- 하나님은 죽은 자를 살리시며 없는 것을 있는 것으로 부르신다.

- 부활과 창조의 능력이고 아브라함은 이 능력의 하나님을 믿었다.

- 그는 바랄 수 없는 중에 하나님의 말씀을 믿었다.

- 세상의 물리법칙으로는 절대로 있을 수 없는 일이지만, 부활과 창조의 하나님께서 말씀하셨기에 아브라함은 그 말씀이 이루어질 것을 의심하지 않고 확실히 믿었다. 

9.적용(나)

- 하나님의 말씀은 반드시 이루어진다.

- 내게 주신 말씀 또한 반듯이 이루어질 것이다.

- 비록 많은 시간이 지나 버티기 힘들지라도 그 말씀이 이루어질 것을 의심하지 않고 확실히 믿고 바라며 기다려야 한다.

10.영적 터치(단어/구절)

  18   아브라함이 바랄 수 없는 중에 바라고 믿었으니

11.믿음과 회개 및 감사기도로 마무리

12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);
