5. 하나님 찾기 (관찰)

- 예수 그리스도로 말미암아 우리를 죄에서 해방시키신 하나님

- 영광으로 예수님을 죽은자 가운데서 살리신 하나님

- 부활의 능력으로 우리를 연합시키신 하나님

6. 인간 찾기 (관찰)

- 그리스도 예수와 합하여 세례를 받은 우리

- 그리스도 예수의 부활과 연합한 우리

- 예수와 함께 십자가에 못 박힌 옛사람

- 예수와 함께 죽음으로 다시 살아날 수 있는 우리

7. 하나님 찾기 (해석) 

- 예수님이 없이 하나님께서 설계하신 인간에 대한 구원 계획을 설명할 길이 없다.

- 예수님으로 말미암아 우리의 죄는 은혜가 되었다. 

- 예수님으로 말미암아 우리는 예수님과 연합하게 되었고, 이 땅에서의 새로운 삶(부활)과 천국에서의 부활을 누리게 되었다.

8. 인간(해석):

- 사도 바울은 예수님을 알기 전의 모습과 알고 난 후의 모습은 달라야 함을 강조한다.

- 예수님을 알았음에도 불구하고 인간은 죄에 빠지기 쉬운 존재이다. 

- 하나님은 우리를 왜 이렇게 연약하게 만드셨을까?

- 그것은 전적으로 하나님을 의지하도록 하기 위함이었을 것이다.

- 어떤 것을 처음 배울 때에 익숙해지기 전까지 얼마나 많은 훈련을 견뎌야하는지 잘 알 것이다.

- 어느 시점이 되면 소위 말하는 베테랑이 된다.

- 우리는 믿음의 베테랑이 되기까지 신앙 훈련을 잘 이겨내야 한다.

- 예수님을 아는 우리는 죄에서 자유함을 얻을 수 있는 은혜를 받았다. 

- 예수님께서 우리를 위해 어떠한 희생과 사랑을 하셨는지 잊지 말고 선한 길을 위해 달려가야겠다.

9. 적용(나):

- 은혜로 하나님을 믿으며 살아가게 하신 것에 감사드린다.

- 죄에 거하지 않고 믿음의 길을 지켜가도록 큐티, 말씀, 예배, 기도를 잘 이어가야겠다. 

