6.인간 찾기(관찰)

- 죄에 대하여 죽은 자가 되고 하나님께 대하여 살아있는 자가 되라

- 자신(의 지체)을 죽은 자 가운데서 다시 살아난 자 같이 하나님께 드려라, 의의 무기로 드려라

- 우리가 은혜 아래에 있으므로 죄가 우리를 주장하지 못한다

- 그렇다 하더라도 우리는 죄를 지어서는 안 된다

- 죄를 짓는 자는 죄의 종으로 사는 것이다

- 우리는 본래 죄의 종이었으나 교훈의 본을 마음으로 순종하여 의의 종이 되었다

- 죄로부터 해방되고 하나님께 종이 되어 거룩함에 이르는 열매를 맺었으니 그 마지막은 영생

