4. 주제만들기: 우리의 연약함을 도우시는 성령님

5. 하나님 찾기 (관찰)

- 우리의 연약함을 도우시는 성령님

- 말할 수 없는 탄식으로 우리를 위해 친히 기도하시는 성령님

- 마음을 살피시는 하나님

- 하나님의 뜻대로 간구하시는 성령님

- 모든 것이 합력하여 선을 이루시는 하나님

- 하나님의 형상을 본받게 하기 위해 미리 정하시고 부르시고, 의롭다 하시고, 영화롭게 하신 하나님

6. 인간 찾기 (관찰)

- 보이지 않는 것을 소망하며 참음으로 기다릴 것을 권면하는 바울

- 우리는 연약하고 마땅히 기도할 바를 알지도 못하지만 하나님의 뜻대로 부르심 받은 자들로써 모든 일을 합력하여 선을 이루는 존재라고 말하는 바울

7. 하나님 찾기 (해석) 

- 하나님은 나약한 존재인 피조물이 육신이 썩어 죽는 것에서 해방시켜 구원을 이루어 주셨다. 

- 그 뿐만 아니라 성령을 보내주셔서 연약한 인간을 도우시고, 깊은 탄식으로 우리를 위해 간구해주시는 분이시다.

- 지금 이 순간에도 우리를 위해 성령님은 깊은 탄식으로 간구하고 계시다.

- 우리는 이 놀라운 사실을 너무 쉽게 잊고 산다. 

- 얼마나 감격스럽고 대단한 일인가? 성령님을 통해 우리를 보호하시는 것 이상으로 우리를 지키시고 인도하고 계시다.

- 하나님은 우리를 친히 택하셨고, 부르셨다.

- 죄에 사로잡힌 우리를 그 분의 사랑으로 의롭다 하셨고, 영화롭게 하셔서, 완전한 구원을 이루어 주시는 분이시다.

- 하나님의 사랑을 잊지 말자

8. 인간(해석):

- 우리는 연약한 존재이기 때문에 세상에서의 영적 전쟁을 승리하기 참 어렵다.

- 사탄은 영적 전쟁에서 무장하면 육체적 연약함을 건드리곤 한다.

- 육체가 무장되면 또 다른 방법으로 우리를 건드린다. 

- 우리는 연약한 존재이다. 

- 그렇다고 우리는 이 전쟁에서 포기해야할까? 아니다. 

- 우리는 오래 참음으로 하나님의 의로우심을 드러내어야 한다. 그것 또한 우리가 할 수 있는 영역은 아니다. 단지 버티기만 잘하면 된다. 

- 다양한 방법으로 잘 버티면, 성령님의 깊은 탄식 가운데 모든 일이 합력하여 하나님의 선하심이 드러난다.

- 포기하지 말고 버텨내야한다. 

9. 적용(나): 

- 하나님이 나를 위해 이루신 일들이 얼마나 많음에도 걱정과 근심 가운데 있는 어리석음을 회개한다. 

- 하나님께서 선을 이루시도록 믿음의 훈련을 잘 해나가야겠다.

- 우리는 결국 승리할 것이다.

10. 영적터치(단어/구절)

- 모든 것이 합력하여 선을 이루느니라

11. 믿음과 회개 및 감사기도로 마무리

