7.하나님 찾기(해석)

- 하나님은 구원의 통로로 사용할 사람을 선택하신다.

- 이 택하심은 에서와 이삭이 리브가의 배에 있을 때에 이루어졌는데,

- 이것으로 보아 하나님의 택하심은 그 사람의 선한 행위나 악한 행위가 근거가 되는 것이 아니라 전적으로 하나님의 부르심에 있는 것을 알 수 있다.

- 하나님의 뜻은 사람의 행위가 아니라 하나님의 부르심과 역사하심으로 말미암아 이루어지는 것이다.

- 하나님께서는 완악한 자도 긍휼히 여기실 자도 선택하시는데 이것에 대해 피조물인 우리 인간이 반문할 수는 없는 것이다.

