- 바울은 피조물과 창조주의 관계를 물건과 물건을 만든 사람으로 비유하며, 지음을 받은 물건이 지은 자에게 왜 나를 이렇게 만들었느냐 말할 수 있느냐 물으며 독자에게 창조주 앞에서 겸손할 것을 강조함

