6. 인간 찾기 (관찰)

복음을 전파하지 않은 인간들

 

7. 하나님 찾기(해석)

하나님은 모든 영혼을 사랑하시며, 모두가 구원받기를 원하신다. 

또한 모든 사람이 부요한 삶을 살기를 바라시고, 자녀들이 부끄러움을 겪는 것도 원하지 않으신다. 즉 하나님은 사랑이 많으시고 공의로우신 분이시다.

누구든지 주의 이름을 부르는 자에게는 천국 시민권을 주신다. 

그곳에는 특별한 조건이 붙지 않는다.

현재 전 세계에서 가장 강대국이라 불리는 미국의 경우, 자국 영주권을 얻기 위해서는 한화로 대략 70억 원을 지급해야 한다고 한다.

 이에 비하면, 미국과는 비교할 수조차 없는 천국의 시민이 되는 문은 누구에게나 크게 열려 있다.

얼마나 큰 축복인가?

얼마나 감사한 일인가?

이 사랑의 하나님을 더욱 의지하고, 더욱 사랑해야겠다는 마음이 든다.

 

8. 인간 찾기(해석)

하나님께서는 모든 인간에게 구원의 길을 열어 주셨지만, 복음을 전하지 않는다면 많은 영혼은 듣지도 못한 채 복음을 받을 기회를 잃게 된다. 

이는 하나님께서 베푸시는 사랑과 자비를 신자의 게으름으로 막아 버리는 것과 같다.

그래서 15절에서는 복음을 “좋은 소식”이라고 표현하며, 그 복음을 전하는 사람의 발을 “아름답도다”라고 비유하고 있다.

우리 남청연(남북 청년연합선교회)의 모든 회원도 이 아름다운 주인공이 되기를 간절히 바란다. 

한 번 이 땅에 태어나 살아가는 인생 가운데, 이보다 더 아름답고 축복된 삶이 또 있을까 생각해 본다.

9. 삶의 적용(구체적으로)

 더 열심히 전도에 힘써야겠다(마포대교 한강대교).

일본선교를 위하여 기도해야겠다

