4.주제 만들기: 하나님의 지혜

5.하나님 찾기(관찰)

- 모든 사람에게 긍휼을 베풀고자 하심

- 하나님의 지혜와 지식은 풍성하다

- 만물이 주에게서 나오고 주로 말미암고 주에게로 돌아감

6.인간 찾기(관찰)

- 누구도 하나님의 판단을 헤아릴 수 없고, 그의 길을 찾지 못할 것이다.

7.하나님 찾기(해석)

- 하나님은 불순종하는 사람들에게 조차 긍휼을 베푸시는 분이시다

- 불순종하던 이방인을 구원하시는 하나님이 이제는 불순종하는 유대인도 구원하실 것이다

- 하나님께서 만물을 창조하시고 통치하시고 심판하시고 영원히 다스리실 것이다.

8.인간 찾기(해석)

- 유대인도 이방인도 하나님의 지혜를 헤아릴 수 없다.

- 하나님의 구원의 방식은 사람의 머리로는 도저히 이해할 수 없는 것이다.

- 구원받은 신자는 하나님의 구원하심을 판단하는 것이 아니라 그저 감사해야 한다.

- 우리는 하나님이 창조하셨고 통치하시며 심판 후에 하나님과 영원히 살 것을 기억해야 한다.

 

9.적용(나) 

- 믿음을 가지고 산다는 것이 그저 즐거울 때가 있고,

- 반대로 힘들 때도 있다.

- 꽃길만 같을 때도 있고 메마른 광야를 걸어가는 듯한 때도 있다.

- 그 때마다 우리가 꼭 기억해야 하는 것은 하나님께서 우리를 창조하셨고 통치하고 계시며 훗날 심판하시고 영원히 우리와 함께 하실 것이라는 것이다.

- 이 말씀은 즐거운 시절 감사와 겸손한 마음을 주고, 힘겨운 시절 인내의 힘을 주는 말씀이다.

10.영적 터치(단어/구절)

  36   이는 만물이 주에게서 나오고 주로 말미암고 주에게로 돌아감이라

