6. 인간 찾기 (관찰)

- 너희 몸을 하나님이 기뻐하시는 거룩한 산 제물로 드리라는 바울

- 거룩한 산 제물은 영적 예배임을 알려주는 바울

- 이 세대를 본 받지 말고 마음을 새롭게 하여 하나님의 뜻을 분별하라 말하는 바울

- 마땅히 생각할 그 이상을 생각하지 말고 하나님께서 나누어 주신 믿음의 분량대로 지혜롭게 생각하라는 바울

- 그리스도 안에서 한 지체가 되었음을 말하는 바울

- 각자에게 주어진 은사에 대해 설명하는 바울 

- 악을 미워하고 선에 속하라는 바울

7. 하나님 찾기 (해석) 

8. 인간(해석):

- 바울은 은사에 대해 설명했다. 특이한 점은 예언 / 섬김, 가르침, 위로 / 구제, 다스림, 긍휼을 달리 설명했다는 점이다. 

- 예언은 믿음의 분수대로 하라고 말한다. 이것은 받아들이는 사람이 시험에 들 수 있으므로 대상에 따라 예언을 신중해야 됨을 뜻하는 것으로 보인다. 

- 섬김, 가르침, 위로는 더하거나, 덜하지 말고, 은사 본연에 소명을 충실히 수행하여야 한다. 경솔하게 행동하거나, 권위 의식을 갖거나, 가식이 있어서는 안 된다.

- 구제는 성실함으로 은사를 감당해야 한다. 성실함은 순수한 마음을 뜻하기도 하다. 구제에 있어서 성실함이 없다면, 자신의 의를 드러내기 위함이 될 수 있다. 그것을 조심하여야 한다.

- 다스리는 자는 부지런해야 하는데 솔선수범이 떠오른다. 리더로서 책임감을 갖고 행동해야 한다. 

- 긍휼을 베푸는 자는 즐거움이 있어야 한다. 즐거운 태도가 없다면 사람을 얇보거나 멸시하는 태도가 근저에 있을 것이다.

 

- 하나님이 각자에게 주어진 은사는 이렇게 다양하다. 남청연 모두 각자 맡은 은사를 잘 감당했으면 좋겠다.

- 혹여나 나에게 주어진 은사가 아님에도 섬김의 과정에서 감당해야할 것들이 있다. 은사가 훈련이 되어 기쁨 마음으로 감당 되어지길 소망해본다.

9. 적용(나): 

- 나에게 주어진 은사를 무엇일까? 그 은사대로 제대로 감당하고 있는지 점검해보아야겠다.

- 우리의 사역이 너무 감사하다. 하나님께 감사 기도를 드려야겠다.

10. 영적터치(단어/구절)

